TP.register({id:"lp8-gk",lp:8,grade:"K",mode:"curriculum",checks:7,nextGrade:"1st grade",build(E){const F=E.F;const TREE="tree",FLOWER="purpleFlower",BIRD="bluebird",SNAIL="snail",BEE="bee",DUCK="duck",EGG="egg",DROP="drop",RAIN="rain",SUN="sun",BOOT="boot",UMBRELLA="umbrella",SPROUT="sprout",CARROT="carrot",LEAF="leaf",BOOK="books",BED="bed",EAR="ear",TALK="speak",CLAP="hand";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const ico=ic;const unit=(e,px,sp)=>`<span style="display:inline-block;margin-right:${sp}">${(F.icon||F.pic2)(e,px)||e}</span>`;const GROW="A seed looks small and dry, but a whole plant is folded up inside it. When a seed is covered with soil and gets water, it starts to swell. First a little root pushes down into the dark soil to drink. Then a thin green shoot pushes up toward the light. The shoot opens two small leaves, and those leaves catch the sunlight. From then on the plant makes its own food out of sunlight, water, and air. That is why a garden needs both rain and sun, and why we water the rows when the rain stays away.";const NAME_LETTERS=["S","p","G","q","A","a","b","d","F","f"];const SOUND_LETTERS=["b","A","s","r","I","f","h","v","k","o"];const DISP="font-family:var(--font-display);font-weight:800";const WRITE_DIR="Draw and write on your paper. Hold it up when you finish.";const LINE_STYLE="font-size:2.2rem;line-height:1.9;margin:0 auto;width:fit-content";function wordGrid(ws){return`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:6px 0 10px">${ws.map(w=>`<div style="border:3px solid var(--line);border-radius:16px;text-align:center;padding:14px 6px;background:var(--surface);${DISP};font-size:clamp(2rem,6vw,3.4rem)">${w}</div>`).join("")}</div>`}const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",SEEDC="#C9875A",STEM="#7FC08A",LEAF_A="#A8D49A",LEAF_B="#BFE3A8",LEAF_INK="#4E7A46",SKY="#C8E9F8",GRASS="#CFE8A8",GRASS_D="#B2D986",GRASS_L1="#A3C777",GRASS_L2="#8EBB64",SOIL="#C08A5E",SOIL_D="#A8724E",WATER="#AFD9EE",WATER_E="#79AFC9",CLOUDC="#E4EFF7",RAINC="#8FC6E4",SUNC="#FBD873",CREAM="#FBF1E4",TIN="#B9C6CE";function seedShape(x,y,s,c,noFace){return window.TP_SEEDIMG(x,y,s)}const seedSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*1.1)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a seed"><g>${seedShape(w*.5,w*.626,w*.91,c)}</g></svg>`;function sprigShape(x,y,s){const k=s/56;return`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})"><path d="M0 12 V-13" fill="none" stroke="${STEM}" stroke-width="5.2" stroke-linecap="round"/><path d="M-2 -13 C-12 -31 -26 -29 -27 -18 C-27 -7 -12 -3 -2 -13 Z" fill="${LEAF_A}" stroke="${LEAF_INK}" stroke-width="2.6" stroke-linejoin="round"/><path d="M2 -13 C12 -31 26 -29 27 -18 C27 -7 12 -3 2 -13 Z" fill="${LEAF_B}" stroke="${LEAF_INK}" stroke-width="2.6" stroke-linejoin="round"/>`+at(0,-16,.44,K_FACE(0,0,11,4))+`</g>`}function canShape(x,y,s){const k=s/110;return`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})"><path d="M-50 -4 L-76 -36 l-16 -2 l-5 19 l16 7 Z" fill="${TIN}" stroke="${INK}" stroke-width="4" stroke-linejoin="round"/><path d="M-52 -14 H16 q8 0 7 9 l-6 40 q-1 9 -10 9 H-43 q-9 0 -10 -9 l-6 -40 q-1 -9 7 -9 Z" fill="${TIN}" stroke="${INK}" stroke-width="4" stroke-linejoin="round"/><path d="M-30 -14 q6 -30 30 -30 q22 0 24 30" fill="none" stroke="${INK}" stroke-width="5" stroke-linecap="round"/><path d="M-50 -2 H14" stroke="#9FAFB8" stroke-width="4" stroke-linecap="round"/>`+at(-18,24,.9,K_FACE(0,0,13,4.4))+`</g>`}const canSvg=w=>`<svg viewBox="0 0 130 100" width="${w}" style="vertical-align:middle" role="img" aria-label="a watering can">${canShape(101,50,110)}</svg>`;function lab(x,y,t,sz,c){return`<text x="${x}" y="${y}" font-size="${sz||24}" font-family="Andika,sans-serif" font-weight="700" fill="${c||"var(--ink)"}" text-anchor="middle">${t}</text>`}const skyBox=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;const plainBox=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;const grassBand=(w,top,h)=>`<path d="M8 ${top} Q${w*.3} ${top-14} ${w*.56} ${top-2} T${w-8} ${top-6} V${top+h} H8 Z" fill="${GRASS}"/><path d="M8 ${top} Q${w*.3} ${top-14} ${w*.56} ${top-2} T${w-8} ${top-6}" fill="none" stroke="${GRASS_L1}" stroke-width="3.2" stroke-linecap="round"/><path d="M8 ${top+30} Q${w*.36} ${top+14} ${w*.64} ${top+28} T${w-8} ${top+24} V${top+h} H8 Z" fill="${GRASS_D}"/><path d="M8 ${top+30} Q${w*.36} ${top+14} ${w*.64} ${top+28} T${w-8} ${top+24}" fill="none" stroke="${GRASS_L2}" stroke-width="3.2" stroke-linecap="round"/>`;const soilRow=(x0,x1,top,h)=>`<rect x="${x0}" y="${top}" width="${x1-x0}" height="${h}" rx="12" fill="${SOIL}" stroke="${INK}" stroke-width="3"/><path d="M${x0+16} ${top+12} q22 -7 44 0 t44 0 t44 0 t44 0 t44 0" fill="none" stroke="${SOIL_D}" stroke-width="3" stroke-linecap="round" opacity=".8"/>`;const puddleShape=(x,y,w)=>`<g><ellipse cx="${x}" cy="${y}" rx="${w/2}" ry="${w/5.2}" fill="${WATER}" stroke="${WATER_E}" stroke-width="2.6"/><path d="M${x-w/4} ${y+2} q${w/8} -5 ${w/4} 0" fill="none" stroke="#FBFEFF" stroke-width="2.6" stroke-linecap="round" opacity=".9"/></g>`;function gardenFig(){const w=620,h=300,base=206;let b=skyBox(w,h);b+=`<circle cx="${w-72}" cy="56" r="34" fill="${SUNC}" opacity=".28"/><circle cx="${w-72}" cy="56" r="23" fill="${SUNC}" stroke="${INK}" stroke-width="3"/>`;b+=grassBand(w,base,h-base-11);b+=F.picXY(118,base-48,TREE,110)+F.picXY(118,74,BIRD,58);b+=F.picXY(300,base-40,FLOWER,92)+F.picXY(300,base+10,SNAIL,52);b+=puddleShape(474,base+24,150)+F.picXY(474,base-10,BOOT,74);b+=lab(118,h-18,"tree",22,"#3E2C22")+lab(300,h-18,"flower",22,"#3E2C22")+lab(474,h-18,"puddle",22,"#3E2C22");return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A garden after the rain. A tree stands on the left with a bird flying above it. A flower grows in the middle with a snail sitting under it. On the right a rain boot stands in a puddle. The sun is out.">${b}</svg>`}function rowFig(n){const w=620,h=190,base=108;let b=skyBox(w,h)+grassBand(w,base,h-base-11);b+=soilRow(26,w-26,base+28,44);for(let i=0;i<n;i++)b+=seedShape(26+(i+.5)*(w-52)/n,base+50,44);return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A row of soil in the garden with ${n} seeds planted along it">${b}</svg>`}function lineBox(e,n,label,cell,size){cell=cell||62;size=size||46;const w=n*cell+56,h=118;let b=plainBox(w,h);for(let i=0;i<n;i++)b+=e==="SEED"?seedShape(28+i*cell+cell/2,56,size):F.picXY(28+i*cell+cell/2,56,e,size);b+=lab(w/2,h-16,label,22,"var(--muted)");return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,600)}" role="img" aria-label="${label}: a line of ${n} pictures">${b}</svg>`}function scatterBox(e,n,seed,label){const W=360,H=250;const pts=[];let x=seed,tries=0,gap=78;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};while(pts.length<n){const p=[48+rnd()*264,44+rnd()*140];if(pts.every(q=>Math.hypot(q[0]-p[0],q[1]-p[1])>gap))pts.push(p);if(++tries>5e3){tries=0;gap-=4}}let b=plainBox(W,H);pts.forEach(p=>{b+=e==="SEED"?seedShape(+p[0].toFixed(0),+p[1].toFixed(0),46):F.picXY(+p[0].toFixed(0),+p[1].toFixed(0),e,44)});b+=lab(W/2,H-18,label,22,"var(--muted)");return`<svg viewBox="0 0 ${W} ${H}" width="340" role="img" aria-label="${label}: ${n} pictures scattered about">${b}</svg>`}function ringBox(e,n,label){const W=300,H=250,cx=150,cy=112,r=78;let b=plainBox(W,H);for(let i=0;i<n;i++){const a=i*2*Math.PI/n-Math.PI/2;b+=e==="SEED"?seedShape(+(cx+r*Math.cos(a)).toFixed(0),+(cy+r*Math.sin(a)).toFixed(0),46):F.picXY(+(cx+r*Math.cos(a)).toFixed(0),+(cy+r*Math.sin(a)).toFixed(0),e,44)}b+=lab(W/2,H-18,label,22,"var(--muted)");return`<svg viewBox="0 0 ${W} ${H}" width="290" role="img" aria-label="${label}: ${n} pictures set out in a ring">${b}</svg>`}function trayFig(loose){const cw=58,per=5,tx=16,ty=22,bw=per*cw,bh=2*cw;const lx=tx+bw+54,lper=4;const w=loose?lx+Math.min(loose,lper)*cw+22:tx+bw+22,h=ty+bh+58;let b=plainBox(w,h);b+=`<rect x="${tx}" y="${ty}" width="${bw}" height="${bh}" rx="10" fill="${CREAM}" stroke="${INK}" stroke-width="3.5"/>`;for(let i=1;i<per;i++)b+=`<path d="M${tx+i*cw} ${ty} V${ty+bh}" stroke="${INK}" stroke-width="2.4"/>`;b+=`<path d="M${tx} ${ty+cw} H${tx+bw}" stroke="${INK}" stroke-width="2.4"/>`;for(let i=0;i<10;i++)b+=seedShape(tx+i%per*cw+cw/2,ty+Math.floor(i/per)*cw+cw/2,44);for(let i=0;i<loose;i++)b+=seedShape(lx+i%lper*cw+cw/2,ty+Math.floor(i/lper)*cw+cw/2,44);b+=lab(tx+bw/2,h-18,"one full tray",22,"var(--muted)");if(loose)b+=lab(lx+Math.min(loose,lper)*cw/2,h-18,"loose seeds",22,"var(--muted)");return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,620)}" role="img" aria-label="A seed tray with ten seeds in it${loose?", and "+loose+" loose seeds beside it":""}">${b}</svg>`}function linesFig(){const tagP=e=>`<span style="line-height:1" aria-hidden="true">${ic(e,40)}</span>`;const line=(a,t,b)=>`<div style="display:flex;align-items:center;justify-content:space-between;gap:16px">${tagP(a)}<span style="${DISP};font-size:clamp(1.7rem,4.4vw,2.9rem);flex:1;text-align:left">${t}</span>${tagP(b)}</div>`;return`<div style="width:fit-content;margin:8px auto 10px;border:6px solid var(--gold-ink);border-radius:16px;background:var(--surface);padding:12px 22px;display:grid;gap:10px">${line(BOOT,"We plant the small seeds.",SPROUT)}${line(RAIN,"The rain is warm.",SUN)}</div><p class="small" style="text-align:center">The four pictures are a boot, a sprout, a rain cloud, and the sun.</p>`}function packChart(){const rows=[[seedSvg(46),"a seed"],[canSvg(72),"watering can"],[BOOT,"rain boots"]];const right=["grows into a plant","gives the plants a drink","keep your feet dry in the mud"];const cell=(pic,word)=>`<span style="display:inline-block;text-align:center;min-width:120px"><span style="display:block;line-height:1.1" aria-hidden="true">${ic(pic,48)}</span><span style="display:block;font-family:var(--font-display);font-weight:700;font-size:1.3rem">${word}</span></span>`;const words=t=>`<span style="display:inline-block;max-width:190px;font-family:var(--font-display);font-weight:700;font-size:1.25rem;text-align:left">${t}</span>`;return`<div class="figure" style="gap:16px;flex-direction:column" role="img" aria-label="Picture chart: a seed grows into a plant, a watering can gives the plants a drink, rain boots keep your feet dry in the mud">`+rows.map((r,i)=>`<div style="display:flex;align-items:center;gap:10px;border:3px solid var(--line);border-radius:18px;padding:10px 16px;background:var(--surface)">${cell(r[0],r[1])}<span style="font-size:2rem;font-weight:800;color:var(--sea)" aria-hidden="true">&#8594;</span>${words(right[i])}</div>`).join("")+`</div>`}function bookFig(){return`<p class="passage" style="${LINE_STYLE}">I see rain.<br>I see sun.<br>I see a seed.<br>It is in a pot.<br>The pot is big.<br>I can dig.<br>The sun is hot.<br>I like the seed.</p><div class="figure" style="gap:14px" aria-hidden="true">${ic(RAIN,48)}${ic(SUN,48)}${seedSvg(44)}</div><p class="small">A seed is small. A seed is dry. A plant starts from seed. Push it in soil. Then water it.</p>`}const COL={red:"#D9423A",blue:"#2F7FD9",green:"#3FA34D",yellow:"#F2C01E",purple:"#8E5BC9",orange:"#E08A2E"};function potsFig(){const w=620,h=196;let b=plainBox(w,h);b+=soilRow(42,292,58,74)+soilRow(330,580,58,74);b+=lab(167,h-22,"pot 1",24,"var(--muted)")+lab(455,h-22,"pot 2",24,"var(--muted)");return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="Two empty pots of soil side by side, pot 1 and pot 2">${b}</svg>`}function hoseFig(){const w=620,h=210;let b=plainBox(w,h);b+=`<path d="M70 32 V178" stroke="var(--line)" stroke-width="3" stroke-dasharray="7 6"/>`;b+=`<path d="M72 74 H492" stroke="${GRASS_L2}" stroke-width="13" stroke-linecap="round"/>`;b+=`<path d="M72 140 H322" stroke="${STEM}" stroke-width="13" stroke-linecap="round"/>`;b+=lab(44,80,"A",26)+lab(44,146,"B",26);b+=lab(w/2,h-16,"both hoses start at the same post",22,"var(--muted)");return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="Two garden hoses lying one above the other. Both start at the same dotted post on the left. Hose A reaches much farther to the right than hose B.">${b}</svg>`}const TRAY_ITEMS=[LEAF,CARROT,FLOWER,LEAF,FLOWER,LEAF,CARROT,LEAF,FLOWER,LEAF,CARROT,FLOWER,LEAF,FLOWER,CARROT,LEAF];function gardenTrayFig(){const per=6,cell=112,w=per*cell+44,h=Math.ceil(TRAY_ITEMS.length/per)*cell+54;let b=plainBox(w,h);TRAY_ITEMS.forEach((e,i)=>{b+=F.picXY(22+i%per*cell+cell/2,24+Math.floor(i/per)*cell+cell/2,e,74)});b+=lab(w/2,h-18,"one tray from the garden",22,"var(--muted)");return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,680)}" role="img" aria-label="A tray holding sixteen garden things mixed together: leaves, carrots and flowers, laid out in three rows">${b}</svg>`}function shedFig(){const st=`stroke="${INK}" stroke-width="4" stroke-linejoin="round"`;let b=`<path d="M40 360 H660" stroke="var(--line)" stroke-width="5" stroke-linecap="round"/>`;b+=`<rect x="200" y="200" width="160" height="160" fill="${COL.blue}" ${st}/>`;b+=`<polygon points="180,200 380,200 280,110" fill="${COL.red}" ${st}/>`;b+=`<rect x="252" y="272" width="60" height="88" fill="${COL.green}" ${st}/>`;b+=`<rect x="214" y="222" width="42" height="42" fill="${COL.purple}" ${st}/>`;b+=`<circle cx="280" cy="52" r="40" fill="${COL.yellow}" ${st}/>`;b+=`<circle cx="470" cy="322" r="38" fill="${COL.orange}" ${st}/>`;return`<svg viewBox="0 0 700 390" width="660" role="img" aria-label="A potting shed built out of shapes: a red triangle roof on a blue square, a green rectangle door and a small purple square window on the square, a yellow circle sun up in the sky straight above the roof, and an orange circle tub standing on the ground beside the shed.">${b}</svg>`}function flatSolidFig(){const st=`stroke="${INK}" stroke-width="3.6" stroke-linejoin="round"`,c=172,w=6*c+28,h=c+52;const tile=i=>`<rect x="${14+i*c}" y="12" width="${c-16}" height="${c-16}" rx="18" fill="var(--surface)" stroke="var(--line)" stroke-width="3.5"/>`;const at0=i=>14+i*c;let b=plainBox(w,h);for(let i=0;i<6;i++)b+=tile(i)+lab(at0(i)+(c-16)/2,h-16,String(i+1),24,"var(--muted)");const g=(i,inner)=>`<g transform="translate(${at0(i)} 12)">${inner}</g>`;b+=g(0,`<circle cx="78" cy="78" r="54" fill="${COL.blue}" ${st}/>`);b+=g(1,`<polygon points="26,54 54,28 136,28 108,54" fill="${COL.green}" ${st}/><polygon points="108,54 136,28 136,110 108,136" fill="${COL.green}" ${st} opacity=".7"/><rect x="26" y="54" width="82" height="82" fill="${COL.green}" ${st}/>`);b+=g(2,`<polygon points="78,26 134,130 22,130" fill="${COL.red}" ${st}/>`);b+=g(3,`<circle cx="78" cy="80" r="54" fill="${COL.orange}" ${st}/><ellipse cx="58" cy="58" rx="19" ry="13" fill="#FFF2DC" opacity=".75" transform="rotate(-30 58 58)"/>`);b+=g(4,`<rect x="26" y="26" width="104" height="104" fill="${COL.purple}" ${st}/>`);b+=g(5,`<rect x="34" y="46" width="88" height="74" fill="${COL.yellow}" ${st}/><ellipse cx="78" cy="120" rx="44" ry="16" fill="${COL.yellow}" ${st}/><ellipse cx="78" cy="46" rx="44" ry="16" fill="#FBE8A8" ${st}/>`);return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,980)}" role="img" aria-label="Six numbered tiles. Tile 1 is a flat blue circle, tile 2 is a green box drawn as a solid, tile 3 is a flat red triangle, tile 4 is an orange ball drawn as a solid, tile 5 is a flat purple square, and tile 6 is a yellow can drawn as a solid.">${b}</svg>`}function wetPathFig(){const w=620,h=220,base=118;let b=skyBox(w,h)+grassBand(w,base,h-base-11);b+=F.picXY(122,56,RAIN,78);b+=soilRow(54,566,base+26,54);b+=puddleShape(206,base+54,128)+puddleShape(430,base+54,106);return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A garden path of dark wet soil the morning after a long rain, with two puddles on it and a rain cloud above">${b}</svg>`}const WORMS="After a long rain, the soil in a garden fills right up with water. Earthworms live in little tunnels down inside that soil. A worm breathes through its skin, so wet soil does not bother it. What a worm cannot do is travel far underground. On a wet morning the top of the ground is damp everywhere, and that is the one time a worm can crawl a long way to a new patch of garden. That is why you find so many worms on the wet path the morning after a rain. Worms are good for a garden. Their tunnels let air and water down to the roots, and the bits they leave behind help new plants grow.";const STOPS=[{id:1,title:"Seed Packet Letters",short:"Packet Letters",parts:[{title:"Name the Letter",std:["RF.K.1"],kind:"words",full:E.alphabet(),words:NAME_LETTERS,unit:"Letter",n:10,dur:40,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters, including look-alike letters",key:["The student says the name of each letter: S, p, G, q, A, a, b, d, F, f. Count a letter correct when the name is right. Sounds are not needed here.","Watch the look-alike pairs: p and q are the second and fourth cards, and b and d are the seventh and eighth. A and a share one name, and so do F and f, so you can hear whether the child knows both shapes. Write down any letters that were missed or mixed up."]},{title:"Two Lines",std:["RF.K.1"],n:3,dur:35,dir:"Look at the two lines. Answer out loud.",desc:"print concepts (counting words and letters)",html:()=>linesFig(),key:["Ask: How many words are in the top line? (5)","Ask: How many words are in the bottom line? (4)","Ask: Look at the first word in the bottom line. How many letters does it have? (3, the word The)"]}]},{id:2,title:"Count the Garden Path",short:"Count",parts:[{title:"Down the Path",std:["K.CC.A.1"],n:3,label:"checks met",dur:60,dir:"Count out loud. Start at 1. Go as high as you can.",desc:"counting out loud by ones",html:()=>`<p class="big" style="text-align:center">The garden is planting a long row. Count out loud as the seeds go in.</p><div class="figure">${ic("sprout",118)}</div>`,key:["Say: Start at 1 and count as high as you can. Check: counts 1 to 20 in order with no skips.","Keeps going from 20 to 40 and gets across each new ten (29 to 30, 39 to 40).","Counts past 50. Stop the student at 100. Write the highest number said before a mistake. The end of year goal is 100."]},{title:"Ten to a Tray",std:["K.CC.A.1"],n:2,label:"checks met",dur:40,dir:"Count by tens out loud.",desc:"counting by tens",html:()=>`<div class="figure">${trayFig(0)}</div><p class="big" style="text-align:center">Each tray holds 10 seeds. Count by tens to 100 as the trays are filled.</p>`,key:["Say: Count the seeds by tens as each tray is filled. Check: says 10, 20, 30, 40, 50 with no help.","Keeps going: 60, 70, 80, 90, 100. Write the last number said in order."]}]},{id:3,title:"Garden Sounds",short:"Sounds",parts:[{title:"Rhyme and Clap",std:["RF.K.2"],n:6,dur:60,dir:"Listen to your teacher. Answer out loud.",desc:"hearing rhymes, making a rhyme, and clapping syllables",html:()=>`<div class="figure">${F.pic(EAR)}${F.pic(CLAP)}</div><p class="small" style="text-align:center">A sprout is the first small green shoot that comes up out of a seed.</p>`,key:["Ask: Do seed and weed rhyme? (yes)","Ask: Do rain and sun rhyme? (no)","Ask: Which word does not rhyme: bug, rug, nest? (nest)","Say: Tell me a word that rhymes with sprout. (shout, out, scout, trout, pout. Silly words count.)","Say: Clap the parts in garden. (2 claps: gar-den)","Say: Clap the parts in butterfly. (3 claps: but-ter-fly)"]},{title:"Put It Together",std:["RF.K.2"],n:6,dur:55,dir:"Listen to your teacher. Answer out loud.",desc:"blending spoken sounds and saying the first, last, and all sounds in a word",html:()=>`<div class="figure">${F.pic(TALK)}${seedSvg(72)}</div>`,key:["Say: Put these sounds together: /r/ /ai/ /n/. (rain)","Say: Put these sounds together: /s/ /ee/ /d/. (seed)","Ask: What is the first sound in bud? (/b/. The sound, not the letter name.)","Ask: What is the first sound in nest? (/n/)","Ask: What is the last sound in root? (/t/)","Say: Tell me every sound in leaf. (/l/ /ea/ /f/, three sounds)"]}]},{id:4,title:"Bud and the Pot",short:"Bud Story",parts:[{std:["RL.K.1"],n:4,dur:85,dir:"Listen while your teacher reads the lines. Then answer out loud.",desc:"asking and answering questions about key details in a story read aloud to the student",html:()=>`<div class="figure" aria-hidden="true">${seedSvg(76)}${ic(SUN,62)}</div><p class="passage" style="${LINE_STYLE}">Bud has a pot.<br>Bud digs in the mud.<br>The sun is hot.<br>Bud sees a bug.</p><p class="small">A pot is a little cup. It holds soil. A plant can grow in it.</p>`,key:["Read the four lines on the screen out loud to the student two times. Point under each word as you read. The student does not read them. Ask: Who is the story about? (Bud)","Ask: Where does Bud dig? (in the mud)","Ask: What does Bud see? (a bug)","Say: Now you ask me a question about Bud. Start with What or Where. (asks a real question about the lines, such as: Where is Bud's pot?)"]}]},{id:5,title:"How Many Seeds",short:"How Many",parts:[{std:["K.CC.B.4"],n:5,dur:85,dir:"Count each box out loud. Then answer out loud.",desc:"counting to tell how many, knowing the last number said is the answer, and knowing the count does not change when the things are moved",fig:()=>F.row(lineBox("SEED",8,"Box A")),fig2:()=>F.row(scatterBox(DROP,7,23,"Box B"),ringBox("SEED",8,"Box C")),key:["Box A. Say: Point to each seed and count out loud. How many seeds are in Box A? (8. Look for one number word per seed, touching each one once.)","Box A again. Do not let the student recount. Ask: How many seeds were in Box A? (8, said straight back. Knowing the last number said is the answer is the whole point here. Having to start over is worth a note.)","Box B. Say: These raindrops are not lined up. Count them and tell me how many. (7. Look for a plan, like touching each one on the screen so none is counted twice.)","Box B again. Say: Now I drop one more raindrop into Box B. How many are there now? (8. Look for the student saying 8 without counting all over again from 1.)","Box C. Say: These are the Box A seeds, moved into a ring. Did the number change? How many are there? (No, the number did not change. 8. Moving things around does not change how many there are.)"]}]},{id:6,title:"Spring Words",short:"Spring Words",parts:[{title:"Letter Sounds",std:["RF.K.3"],kind:"words",words:SOUND_LETTERS,unit:"Letter",n:10,dur:45,dir:"Say the sound each letter makes.",desc:"saying the sounds of letters",key:["The student says the most common sound for each letter: b /b/, A as in apple, s /s/, r /r/, I as in itch, f /f/, h /h/, v /v/, k /k/, o as in otter. The letter name is not needed here.","The long sound for A or I is also fine. Write down any sounds that were missed."]},{title:"Garden Words",std:["RF.K.3"],n:9,dur:55,dir:"Read each word out loud.",desc:"reading high-frequency words and short vowel words",html:()=>wordGrid(["me","she","to","and","you","bud","wet","pot","dig"]),key:["High-frequency words the student should know by sight: me, she, to, and, you","Sounds out or reads: bud, wet, pot, dig","Score is the number of words read correctly out of 9. Write down which ones were missed."]}]},{id:7,title:"Listen to the Garden",short:"Listen",parts:[{std:["SL.K.2"],n:5,dur:70,dir:"Put your eyes on your teacher and listen. Then answer out loud.",desc:"answering questions about key details in a text read aloud and asking for help",html:()=>`<div class="figure">${F.pic(EAR)}${seedSvg(74)}</div><p class="big" style="text-align:center">Listening time. Your teacher will read you a report about how a seed grows.</p>`,read:GROW,key:["Ask: What is folded up inside a seed? (a whole plant)","Ask: What two things does a seed need before it starts to swell? (soil covering it, and water)","Ask: Which part comes out first, the root or the shoot? Which way does it go? (the root first, and it pushes down into the soil)","Ask: What do the two small leaves catch? (the sunlight)","Say: Pretend you missed one part. What can you say to me? (asks for help, such as: Can you read that part again? or What is a shoot?)"]}]},{id:8,title:"Seeds in the Row",short:"Add It",parts:[{std:["K.OA.A.2"],n:5,dur:100,dir:"Listen to each story. You can draw on your paper. Say your answer out loud.",desc:"addition and subtraction word problems within 10, with drawings",html:()=>`<div class="figure">${rowFig(5)}</div><p class="small" style="text-align:center">You can draw a circle for each seed on your paper, then count or cross out.</p>`,key:["Say: 4 seeds go in the first row. 3 more seeds go in the second row. How many seeds in all? (7. 4 + 3 = 7)","Say: 9 raindrops were on the window. 2 of them slid down. How many raindrops can you still see? (7. 9 - 2 = 7)","Say: 5 sprouts are up. Then 4 more come up. How many sprouts now? (9. 5 + 4 = 9)","Say: There are 10 eggs in the nest. 3 of them hatch. How many are still eggs? (7. 10 - 3 = 7)","Say: 2 bees are on the flower and 6 more bees fly over. How many bees in all? (8. 2 + 6 = 8)","Drawing, fingers, or counters all count. Note whether the student counted every one from 1 or counted on from the bigger number."]}]},{id:9,title:"Ten and Some More",short:"Ten More",parts:[{std:["K.NBT.A.1"],n:5,dur:90,dir:"Look at the trays. Count out loud. You can draw on your paper.",desc:"putting numbers from 11 to 19 together as one ten and some more ones",fig:()=>F.row(trayFig(5)),fig2:()=>F.row(trayFig(8)),qs:["Look at the first picture. How many seeds are in the full tray?","In the first picture, how many loose seeds are there? How many seeds in all?","Say it the ten way. Fifteen is ten and how many more?","Look at the second picture. Count the loose seeds. What number is ten and that many more?","Say thirteen the ten way. Thirteen is ten and how many more?"],key:["10. A full tray always holds ten.","5 loose seeds. 15 seeds in all. Look for the student counting on from 10 (11, 12, 13, 14, 15) rather than starting over at 1.","5 more. Fifteen is ten and five.","8 loose seeds. Ten and eight more is 18.","3 more. Thirteen is ten and three. Drawing a full tray and 3 loose seeds counts as showing it."]}]},{id:10,title:"Little Spring Book",short:"Spring Book",parts:[{std:["RF.K.4"],n:30,label:"words read correctly",dur:55,dir:"Point to each word and read it out loud.",desc:"reading a short emergent-reader book with purpose and understanding",html:()=>bookFig(),key:["Count the words the student reads correctly, out of 30, and enter the number in the box. A word the student fixes without help counts. Write down the words that were missed.","Points or tracks under each word, left to right and top to bottom","Reads most of the words correctly, including the sight words I, see, the, is, a, in. Picture words, carried by the picture beside them: rain, seed. The rest are sight words or sound-out words (sun, pot, dig, hot)","Ask: What is this little book about? (the rain and the sun, or a seed that got planted in a pot)"]}]},{id:11,title:"Garden Talk",short:"Talk",parts:[{std:["L.K.1"],n:5,dur:70,dir:"Look at the picture. Listen to your teacher. Say your answer out loud.",desc:"spoken grammar items (plural nouns, question words, position words in complete sentences)",html:()=>`<div class="figure">${gardenFig()}</div>`,key:["Say: One seed, two ____. (seeds)","Say: One bush, two ____. (bushes)","Say: Ask me a question that starts with Where. (asks a where question)","Say: Look at the picture. Where is the snail? Tell me in a whole sentence. (a complete sentence with under, such as: The snail is under the flower.)","Say: Where is the boot? Tell me in a whole sentence. (a complete sentence with in, such as: The boot is in the puddle.)"]}]},{id:12,title:"Spring Notebook",short:"Write",parts:[{wk:"opinion",alt:{group:"write",label:"Plant or Splash",icon:"💬",hint:"Draw it and tell what you think"},std:["W.K.1"],n:3,label:"checks met",dur:140,dir:WRITE_DIR,desc:"a draw-and-write opinion piece about planting seeds or splashing in puddles",html:()=>`<div class="figure">${seedSvg(56)}${ic(BOOT,58)}</div><p class="big">Would you rather plant a row of seeds, or splash in the puddles after the rain? Draw the one you pick. Write or tell what you think and why.</p>`,key:["Tells the reader what the choice is about: planting seeds or splashing in puddles (W.K.1)","States an opinion, which one the student would pick. Drawing, telling, or writing all count (W.K.1)","Gives a reason or a detail for the pick, such as: I like the mud, or Seeds grow into food (W.K.1)"]},{wk:"facts",alt:{group:"write",label:"Spring Facts",icon:"📖",hint:"Draw it and tell one true thing"},std:["W.K.2"],n:3,label:"checks met",dur:140,dir:WRITE_DIR,desc:"a draw-and-write informative piece about a seed, a bird, or the rain",html:()=>`<div class="figure">${seedSvg(56)}${ic(BIRD,58)}${ic(RAIN,58)}</div><p class="big">Pick one: a seed, a bird, or the rain. Draw it. Write its name. Then write or tell one true thing about it.</p><p class="small">A seed is a small thing. It is dry. A plant starts from it.</p>`,key:["Names what the drawing and writing are about: a seed, a bird, or the rain (W.K.2). The student may say it, label the picture, or write a letter or word for it","Gives at least one piece of true information about it, such as: A seed grows into a plant. A bird builds a nest. Rain makes the grass wet (W.K.2)","Uses drawing, telling, or writing (any mix) to get the information across (W.K.2)"]}]},{id:13,title:"Garden Day List",short:"The List",parts:[{std:["W.K.8"],dur:55,dir:"Look at the chart. Answer out loud.",desc:"answering questions from a picture chart and from experience",fig:()=>packChart(),qs:["Look at the chart. What grows into a plant?","Look at the chart. What gives the plants a drink?","Look at the chart. What keeps your feet dry in the mud?","Think about the last rainy day. What is one thing you did when the rain stopped?"],key:["The seed. Uses the chart to answer.","The watering can. Uses the chart to answer.","The rain boots. Uses the chart to answer.","Names one real thing, such as went outside, jumped in a puddle, or looked for worms. Recalls it from experience."]}]},{id:14,title:"Tell Me More",short:"Tell More",parts:[{std:["SL.K.4"],n:3,label:"checks met",dur:55,dir:"Tell your teacher out loud. Use lots of details.",desc:"describing a familiar thing you do outside, with details",html:()=>`<div class="figure">${F.pic(BOOT)}${F.pic(UMBRELLA)}${F.pic(FLOWER)}</div><p class="big" style="text-align:center">Tell me about something you like to do outside when it gets warm.</p>`,key:["Names the thing and tells something about it","Adds a detail when you ask: Where do you do it?","Adds another detail when you ask: Who is with you, and what do you see or hear?"]}]},{id:15,title:"Greater, Less, or Equal",short:"Compare",parts:[{std:["K.CC.C.6"],n:3,dur:60,dir:"Count each box out loud. Then answer out loud.",desc:"telling whether one group is greater than, less than, or equal to another group",fig:()=>F.row(lineBox(SPROUT,9,"Box D",64,48),scatterBox(DROP,6,47,"Box E")),fig2:()=>F.row(lineBox(BEE,7,"Box F",64,48),lineBox(EGG,7,"Box G",64,48)),key:["Say: Count Box D and Box E. Which group is greater? How do you know? (Box D is greater. 9 sprouts in a line and 6 raindrops spread about. Counting both, or matching one raindrop to one sprout, both count. Ask for the how-you-know part: saying greater without a count or a match is only half of it.)","Say: Now say it the other way. Which group is less? (Box E. 6 is less than 9.)","Say: Count Box F and Box G. Are they greater, less, or equal? (Equal. 7 bees and 7 eggs.)","Listen for the words greater than, less than, or equal to. Fewer and more are a fine start at this grade, but write down which words the student used."]}]},{id:16,title:"Seven Seeds, Two Pots",short:"Split It",parts:[{std:["K.OA.A.3"],n:3,dur:65,dir:"Look at the seeds and the two pots. You can draw on your paper. Say your answer out loud.",desc:"breaking 7 into two parts in more than one way and recording one way",fig:()=>F.row(lineBox("SEED",7,"seven seeds",64,48)),fig2:()=>F.row(potsFig()),key:["Say: You have 7 seeds and two pots. Show me one way to put all 7 seeds into the two pots. Draw it or tell me. (Any pair that makes 7: 1 and 6, 2 and 5, 3 and 4, 4 and 3, 5 and 2, 6 and 1. Putting all 7 in one pot and 0 in the other counts too.)","Say: Now show me a different way. (A second pair that makes 7 and is not the one just given.)","Say: Pick one of your ways and say it as a number sentence. (7 = 3 + 4, or 3 + 4 = 7, or whichever pair the student used. Writing it on paper counts, and so does saying it out loud.)","Count the first two checks only when the two parts really add to 7. If a way does not make 7, count the seeds together with the student and note it."]}]},{id:17,title:"Two Hoses",short:"Longer",parts:[{std:["K.MD.A.2"],n:3,dur:55,dir:"Look at the two hoses. Answer out loud.",desc:"comparing two objects directly by length and describing the difference",fig:()=>F.row(hoseFig()),key:["Say: Which hose is longer, A or B? (A)","Say: How do you know? (Both hoses start at the same post, so the one whose far end reaches farther is the longer one. Look for the student lining up the starts, not only pointing at the picture.)","Say: Now tell me about hose B in one whole sentence, using the word shorter. (Hose B is shorter than hose A. The sentence has to name both hoses and use shorter or not as long.)"]}]},{id:18,title:"Sort the Garden Tray",short:"Sort",parts:[{std:["K.MD.B.3"],n:3,dur:65,dir:"Look at the tray. Answer out loud.",desc:"sorting into three given kinds, counting each kind, and putting the kinds in order by count",fig:()=>F.row(gardenTrayFig()),key:["Say: This tray came in from the garden. Sort it into three kinds: leaves, carrots and flowers. How many of each? (7 leaves, 4 carrots, 5 flowers)","Say: Which kind has the most? Which kind has the fewest? (Leaves the most, with 7. Carrots the fewest, with 4.)","Say: Now put all three kinds in order, from the fewest to the most. (carrots 4, then flowers 5, then leaves 7) Count it correct when all three are in the right order.","There are 16 things on the tray. If the student loses track while counting one kind, suggest pointing at each one, and note that the counting needed a strategy."]}]},{id:19,title:"The Potting Shed",short:"Shapes",parts:[{title:"Shed Shapes",std:["K.G.A.1"],n:3,dur:60,dir:"Look at the potting shed. Answer out loud.",desc:"naming shapes in a scene and telling where things are with position words",fig:()=>F.row(shedFig()),key:["Say: The potting shed is built out of shapes. What shape is the roof? What shape is the big part under it? (A triangle. A square.)","Say: What shape is the door? What shape is the little window? (The door is a rectangle. The window is a square.)","Say: Where is the yellow circle sun, and where is the orange circle tub? (The sun is above the shed or above the roof. The tub is beside the shed, or next to it. Count this correct only when both answers use a position word.)"]},{title:"Flat or Solid",std:["K.G.A.3"],n:3,dur:55,dir:"Look at the six tiles. Answer out loud.",desc:"telling flat two-dimensional shapes from solid three-dimensional ones",fig:()=>F.row(flatSolidFig()),key:["Say: Some of these shapes are flat and some are solid. Which ones are flat? (1, 3 and 5: the circle, the triangle and the square.)","Say: Which ones are solid? (2, 4 and 6: the box, the ball and the can.)","Say: How can you tell a solid shape from a flat one? (A flat shape lies flat, like something drawn on paper. A solid shape is fat, you can hold it in your hand and turn it around. Any answer that says a solid one takes up space counts.)","Naming the solid shapes as a cube, a sphere and a cylinder is above what this standard asks. If the student uses those words, write it down."]}]},{id:20,title:"Worms on the Path",short:"Worm Facts",parts:[{std:["RI.K.1"],n:3,dur:70,sup:true,read:WORMS,dir:"Listen to your teacher read about worms. Then answer out loud.",desc:"answering and asking questions about key details in an informational text read aloud",fig:()=>F.row(wetPathFig()),key:["If picture supports are on, point to the picture first. Say: This is the garden path the morning after a long rain. Then read the facts out loud.","Ask: Why do the worms come up onto the path after it rains? (The top of the ground is damp everywhere, and that is the one time a worm can crawl a long way to a new patch of garden. A worm cannot travel far underground.) Reading the two sentences again is allowed. Note it if you did.","Ask: Tell me one way worms help a garden. (Their tunnels let air and water down to the roots. The bits they leave behind help new plants grow. Either one counts.)","Say: Now you ask me a question about the worms. Start with What, Where, or Why. (Asks a real question, such as: Where do the worms go after? What do worms eat? Telling a fact back instead of asking does not count.)"]}]},{id:21,title:"A Rainy Day Story",short:"My Story",parts:[{std:["W.K.3"],wk:"narrative",n:3,label:"checks met",dur:75,dir:WRITE_DIR,desc:"a draw-and-tell story about one real thing that happened, in order, with a reaction",html:()=>`<div class="figure">${ic(RAIN,56)}${ic(BOOT,56)}${seedSvg(52)}</div><p class="big">Think of one time you were out in the rain, or one time you helped something grow. Draw what happened. Then tell it in order. Then tell how it felt.</p>`,key:["Tells about one real thing that happened, using any mix of drawing, telling and writing (W.K.3)","Tells the parts in the order they happened. Look for at least two things in the right order, or for words like first, then, next, after (W.K.3)","Gives a reaction to what happened, such as: It was fun. I was cold. I liked it. I was so happy when it came up (W.K.3)","Telling the story out loud is enough at this grade. The drawing and any letters are a plus, not a requirement."]}]},{id:22,title:"What Living Things Need",short:"Living Things",parts:[{std:["K-LS1-1"],n:3,dur:75,dir:"Look at each row. Answer out loud.",desc:"telling what plants and animals need to stay alive",html:()=>`<p class="big">A tulip and a bee both live in the spring garden. Living things need certain things to stay alive.</p>
     <div class="figure">${ico("tulip",96)}${ico("bee",96)}</div>`,qs:["A tulip needs two of these to grow. Which two? Water, sunlight, or a ribbon?","A bee needs two of these. Which two? Food, water, or a bell?","Name one thing the tulip and the bee both need."],key:["water and sunlight. A ribbon is not something a tulip needs.","food and water. A bell is not something a bee needs.","water. Accept food only if the student explains that a tulip makes its own out of sunlight."]}]},{id:23,title:"A Week of Spring Weather",short:"Weather",parts:[{std:["K-ESS2-1"],n:3,dur:75,dir:"Look at the week of weather. Answer out loud.",desc:"describing a weather pattern from a week of observations",html:()=>`<p class="big">Here is one week of weather over the garden.</p>
     <table class="bigTable"><tr><th>Mon</th><th>Tue</th><th>Wed</th><th>Thu</th><th>Fri</th><th>Sat</th></tr>
     <tr><td>${ico("rain",58)}</td><td>${ico("rain",58)}</td><td>${ico("cloud",58)}</td><td>${ico("rain",58)}</td><td>${ico("sun",58)}</td><td>${ico("rain",58)}</td></tr></table>`,qs:["How many rainy days were there?","How many sunny days were there?","Which kind of weather happened the most this week?"],key:["4","1","rainy. Counting the pictures is the evidence. Ask a student who answers fast to point and count for you."]},{std:["K-ESS2-2"],n:2,dur:60,dir:"Answer out loud.",desc:"telling how a living thing changes its surroundings to get what it needs",html:()=>`<p class="big">A squirrel comes into the garden bed carrying an acorn.</p>
     <div class="figure">${ico("squirrel",88)}${ico("acorn",88)}</div>`,qs:["The squirrel digs a hole in the soft dirt and buries the acorn to save it for later. Did the squirrel change the garden bed, or did the garden bed change the squirrel?","Tell me one way you change a yard or a garden to get what you need."],key:["The squirrel changed the garden bed. There is a hole and a buried acorn that were not there before.","Any sensible answer about changing a space on purpose: pulling weeds out of a row, digging a hole for a seed, moving a pot into the sun, raking leaves off a path."]}]},{id:24,title:"Homes, Reports and the Garden",short:"Homes",parts:[{std:["K-ESS3-1"],n:3,dur:75,dir:"Match each animal to the place it lives. Answer out loud.",desc:"matching animals to the places that give them what they need",html:()=>`<p class="big">Animals live in the garden. Each one lives in one place. It gets what it needs.</p>
     <div class="figure">${ico("ladybug",80)}${ico("frog",80)}${ico("rabbit",80)}</div>
     <p class="big">Here are the places. A leaf. The pond. A burrow under the hedge.</p>`,qs:["Where does the ladybug live?","Where does the frog live?","Where does the rabbit live?"],key:["a leaf. Accept a plant or a stem.","the pond. Accept the water.","a burrow under the hedge. Accept a hole in the ground or a den."]},{std:["K-ESS3-2"],dur:75,dir:"Answer out loud.",desc:"telling what a weather forecast is for",html:()=>`<p class="big">The day before the class plants their seedlings outside, their teacher checks the weather report on her phone.</p>
     <div class="figure">${ico("phone",88)}${ico("rain",88)}</div>`,qs:["Why does she check the weather report? To find out if a hard rain is coming so they can wait a day, or to find out what color the flowers will be?","What could the class do if a hard rain was coming?","They want to pick a good day to plant. What is one question they could ask about the weather?"],key:["to find out if a hard rain is coming so they can wait a day.","Any sensible answer: wait a day, cover the row, plant in the morning before it starts.","Any real weather question: will it rain, how much rain will there be, will it be windy."]},{std:["K-ESS3-3"],n:2,dur:60,dir:"Answer out loud.",desc:"telling one way people can take better care of the land and water",html:()=>`<p class="big">Two children water the garden rows with a hose.</p>
     <div class="figure">${ico("wateringCan",96)}${ico("drop",96)}</div>`,qs:["One child turns the hose off as soon as the row is full. The other child leaves the hose running all afternoon. Which choice takes better care of the water?","Tell me one more way to take care of the land or the water."],key:["turning the hose off as soon as the row is full","Any sensible answer: put a weed pile in the compost, do not pour paint water on the ground, use a watering can instead of a running hose, pick up the plastic pots, plant something."]}]},{id:25,title:"Pushes and Pulls in the Garden",short:"Push and Pull",parts:[{std:["K-PS2-1"],n:3,dur:75,dir:"Answer out loud. Do not say push or pull for the student.",desc:"telling a push from a pull, and comparing a strong push with a gentle one",html:()=>`<p class="big">A push moves something away from you. A pull brings it toward you.</p>
     <div class="figure">${ico("hand",88)}${ico("sprout",88)}</div>`,qs:["You pull the garden gate toward you to open it. Is that a push or a pull?","You press a seed down into the soil with your thumb. Is that a push or a pull?","You give the garden swing a gentle push, then a strong push. Which push sends it higher?"],key:["a pull","a push","the strong push. A stronger push moves a thing farther."]},{std:["K-PS2-2"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"deciding whether a change made a thing move farther or in a new direction",html:()=>`<p class="big">The class let the wind carry the same paper kite across the lawn twice.</p>
     <table class="bigTable"><tr><th>The wind</th><th>How far the kite moved</th></tr>
     <tr><td>a strong gust</td><td>9 steps</td></tr><tr><td>a soft puff</td><td>2 steps</td></tr></table>`,qs:["Which wind moved the kite farther?","A ball is rolling straight down the garden path. You tap it on its side with a stick. Does it keep going straight, or does it turn?"],key:["the strong gust, 9 steps","It turns. The tap from the side changes the direction it was going."]}]},{id:26,title:"Sun and Shade in the Garden",short:"Sun",parts:[{std:["K-PS3-1"],n:2,dur:60,dir:"Answer out loud. If you can, touch a sunny spot and a shady spot together first.",desc:"telling what sunlight does to the ground and to the things on it",html:()=>`<p class="big">Two watering cans stand full of water all morning. One sits out in the open. One sits under a leafy bush.</p>
     <div class="figure">${ico("wateringCan",88)}${ico("tree",88)}</div>`,qs:["What warms the water in the can, sunlight or moonlight?","Which can of water is warmer by lunchtime, the one in the open or the one under the bush?"],key:["sunlight","the one in the open, because the sunlight reaches it"]},{std:["K-PS3-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"designing and drawing something that keeps a spot cooler",html:()=>`<p class="big">The new seedlings are here. They are in the garden. They droop in the hot sun. The afternoon sun is hot. Draw something to shade the row of seedlings, like a cloth on sticks, a row of tall sunflowers, or a paper tent.</p>
     <div class="figure">${ico("sprout",88)}${ico("sunflower",88)}</div>`,qs:["Draw your shade cover over the row of seedlings.","Tell me how your cover keeps the seedlings cooler."],key:["Any cover drawn ABOVE the row. The three examples are in the direction, so copying one still counts. A cover drawn beside the row is partial: ask where the sun is coming from.","Something like: it blocks the sun, the sun cannot reach the leaves, it puts the row in a shadow."]}]},{id:27,title:"Solving a Garden Problem",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Listen, then answer out loud.",desc:"naming a problem people want to fix and asking about it",read:"Tess fills the open bird feeder in the garden every morning. Spring rain comes nearly every afternoon, and by evening the seed has soaked into a wet lump that the birds will not eat.",qs:["What is the problem? The rain soaks the bird seed, or the feeder is made of wood?","Ask me one question that would help you fix it."],key:["The rain soaks the bird seed.","Any real question: how hard does it rain, how much seed is in there, is the top open, could we move the feeder. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"drawing something whose shape would solve the problem",html:()=>`<p class="big">Draw something that would keep the rain off the bird seed, like a little roof, a lid, or an umbrella over the feeder.</p>
     <div class="figure">${ico("birdhouse",88)}${ico("umbrella",88)}</div>`,qs:["Draw your fix.","Tell me what you drew and how its shape keeps the rain out."],key:["Any cover that would turn rain away: a roof, a lid, a wide hat shape, an upside down bowl, an umbrella. The three examples are in the direction, so copying one earns credit.","Naming it is what shows intent. Something like: the roof sends the rain off the side, the lid stops it getting in."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"comparing test results from two fixes for the same problem",html:()=>`<p class="big">The class tried two covers and measured the wet seed after one rainy afternoon.</p>
     <table class="bigTable"><tr><th>Cover</th><th>Wet seed</th></tr>
     <tr><td>a slanted roof</td><td>1 spoon</td></tr><tr><td>a flat lid laid on top</td><td>6 spoons</td></tr></table>`,qs:["Which cover worked better?","How do you know?"],key:["the slanted roof","Because only 1 spoon of seed got wet under the slanted roof and 6 spoons got wet under the flat lid. The reason has to come from the chart, not from liking roofs."]}]},{id:28,title:"Garden Rules and Doing Right",short:"Rules",parts:[{std:["HSS-K.1"],n:3,dur:75,dir:"Listen, then answer out loud.",desc:"following rules, knowing what happens when they are broken, and naming an honest choice",read:"Tess was carrying the seed tray to the window. Her sleeve caught the edge and three little pots tipped over. Soil went all across the floor. Nobody was looking. Tess stood still and thought about it. Then she found her teacher and said, I knocked the pots over. I will sweep it up. Her teacher brought the dustpan and swept with her.",qs:["What did Tess choose to do? Tell the truth, or walk away and say nothing?","One garden rule is wait for your turn with the watering can. What might happen if nobody waited for a turn?","Tell me one rule you follow at your house, and say why that rule is there."],key:["She told the truth.","Everybody grabs at once, the can gets spilled, and somebody never gets a turn. Any real consequence counts.","Any rule with a reason attached. The reason is the part to listen for."]}]},{id:29,title:"A Map of the Garden",short:"Maps",parts:[{std:["HSS-K.4"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"telling land from water on a map, using position words, and naming the jobs people do nearby",html:()=>`<p class="big">Here is a map of the garden.</p>
     <div class="figure"><svg viewBox="0 0 300 180" width="300" height="180" role="img" aria-label="A map showing water around an island with a house and a tree"><rect x="2" y="2" width="296" height="176" rx="14" fill="#BFE3F5" stroke="#6B4A3C" stroke-width="3"/><g stroke="#5E8FA8" stroke-width="3" stroke-linecap="round" fill="none"><path d="M22 34 q10 -8 20 0 t20 0"/><path d="M232 34 q10 -8 20 0 t20 0"/><path d="M22 150 q10 -8 20 0 t20 0"/><path d="M232 150 q10 -8 20 0 t20 0"/><path d="M22 92 q10 -8 20 0 t20 0"/><path d="M232 92 q10 -8 20 0 t20 0"/></g><ellipse cx="150" cy="90" rx="92" ry="54" fill="#A8D49A" stroke="#6B4A3C" stroke-width="3"/><g transform="translate(110,92)"><rect x="-20" y="-6" width="40" height="32" rx="4" fill="#F2E3C6" stroke="#6B4A3C" stroke-width="3"/><path d="M-26 -6 L0 -28 L26 -6 Z" fill="#D9704F" stroke="#6B4A3C" stroke-width="3" stroke-linejoin="round"/><rect x="-7" y="8" width="14" height="18" rx="2" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.4"/></g><g transform="translate(192,92)"><rect x="-6" y="2" width="12" height="24" rx="3" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.6"/><circle cx="0" cy="-8" r="22" fill="#6FB762" stroke="#6B4A3C" stroke-width="3"/></g></svg></div>
     <p class="big">${ico("cabin",64)} the shed &nbsp;&nbsp; ${ico("purpleFlower",64)} the flower beds &nbsp;&nbsp; ${ico("tree",64)} the apple tree</p>`,qs:["On this map, which color shows the water and which color shows the land?","The shed is behind the flower beds. The apple tree is in front of them. Which one is behind?","Is the apple tree near the shed or far from it?","Name two people who work in your neighborhood, and tell me what each one does."],key:["The blue part shows water and the green or brown part shows land.","the shed","Either answer is fine as long as the student points and explains. The position word is what is being checked.","Any two real workers with a job attached: a mail carrier brings the mail, a nurse helps sick people, a store clerk rings up food, a bus driver drives the bus. A job with no worker, or a worker with no job, is half."]}]},{id:30,title:"The Flag and Long Ago",short:"Long Ago",parts:[{std:["HSS-K.2"],n:2,dur:60,dir:"Answer out loud.",desc:"recognizing the flag as a symbol of the country",html:()=>`<p class="big">California has state symbols too. They are its own. The state flower is a poppy. It is golden. The state animal is a bear. It is a grizzly. The state bird is a quail. It is the California quail.</p>
      <div class="figure">${ico("flag",120)}</div>`,qs:["What do we call this, and what country is it for?","California has its own symbols as well. Name the state flower or the state animal of California."],key:["the flag. Accept the American flag or the flag of the United States. Naming it as our flag counts.","the golden poppy for the flower, or the grizzly bear for the animal. Accept the California quail as the state bird. A state symbol is the other half of this standard. (HSS-K.2)"]},{std:["HSS-K.6"],n:3,dur:75,dir:"Answer out loud.",desc:"telling what a holiday honors and how life long ago was different from life today",html:()=>`<p class="big">Long ago there were no garden hoses.</p>
     <div class="figure">${ico("wateringCan",96)}${ico("drop",96)}</div>`,qs:["How did people long ago bring water to a garden, by carrying it from a well in buckets or by turning on a hose?","How do you give a plant water today?","Independence Day is a day our whole country remembers together. Is a day like that for remembering something, or is it only a day off from school?"],key:["by carrying it from a well in buckets","Any real answer: a hose, a watering can, a cup, the rain. Naming today's way is the then-and-now half of this standard.","a day for remembering something. Follow up: what do you think we remember on that day? Any reasonable answer counts at this age."]}]}];const LEVELUPS={1:{id:"L1",lv:true,title:"Level Up: Sentence Parts",std:["RF.1.1"],needs:["RF.K.1"],n:3,dir:"Look at the sentence. Answer out loud.",html:()=>`<p class="passage" style="font-size:2.4rem;text-align:center;margin:0 auto;width:fit-content">The rain fills the puddle.</p><ol class="qlist"><li>Which word is the first word of the sentence?</li><li>Why does that word start with a big letter?</li><li>What mark is at the end of the sentence?</li></ol>`,key:["The","Because it is the first word of the sentence. Sentences start with a capital letter.","A period, or a dot"]},2:{id:"L2",lv:true,title:"Level Up: Count to 120",std:["1.NBT.A.1"],needs:["K.CC.A.1"],n:2,dir:"Count out loud. Then read the numbers.",html:()=>`<ol class="qlist"><li>Start at 112. Count out loud to 120.</li><li>Read each number.</li></ol>${wordGrid(["58","107","119"])}`,key:["112, 113, 114, 115, 116, 117, 118, 119, 120 with no skips.","Reads fifty-eight, one hundred seven, one hundred nineteen"]},4:{id:"L4",lv:true,title:"Level Up: Read a Story",std:["RL.1.1"],needs:["RL.K.1"],n:2,dir:"Read the story out loud. Then answer out loud.",html:()=>`<p class="passage" style="font-size:2rem;line-height:1.8">Rosa pulled on her boots and ran out to the row she had planted. The soil was still dark from the rain. Right in the middle, one tiny green sprout was standing up. Rosa knelt down and counted the leaves. There were two.</p><ol class="qlist"><li>What did Rosa pull on before she ran out?</li><li>How many leaves did the sprout have?</li></ol>`,key:["Her boots","Two"]},6:{id:"L6",lv:true,title:"Level Up: Tricky Words",std:["RF.1.3"],needs:["RF.K.3"],n:3,dir:"Read each word out loud.",html:()=>wordGrid(["chop","when","vine"]),key:["Reads the first word (ch digraph, short o)","Reads the second word (wh digraph, short e)","Reads the third word (final e, long i)"]},9:{id:"L9",lv:true,title:"Level Up: Tens and Ones",std:["1.NBT.B.2"],needs:["K.NBT.A.1"],n:3,dir:"Look at the blocks. Answer out loud.",html:()=>`<div class="figure">${F.tens(3,6)}</div><ol class="qlist"><li>How many tens and how many ones do you see? What number is that?</li><li>In the number 47, what does the 4 stand for?</li><li>How many tens are in 90? How many ones are left over?</li></ol>`,key:["3 tens and 6 ones. That is 36","The 4 stands for four tens, which is forty","9 tens, and 0 ones left over"]},11:{id:"L11",lv:true,title:"Level Up: Garden Grammar",std:["L.1.1"],needs:["L.K.1"],n:3,dir:"Listen to your teacher. Say your answer out loud.",html:()=>`<div class="figure">${gardenFig()}</div><ol class="qlist"><li>Today we water the row. Yesterday we ____ the row.</li><li>Which sounds right? The bird sing in the tree. Or: The bird sings in the tree.</li><li>Join these two sentences with the word <b>and</b>: The rain stopped. The sun came out.</li></ol>`,key:["watered (the past tense -ed ending)","The second one. One bird goes with the verb sings","The rain stopped, and the sun came out"]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=40;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}const STARTERS={opinion:["I would pick ____.","I like it because ____.","That is why I would pick it."],facts:["This is a ____.","It is ____.","One true thing is ____."],narrative:["One time I ____.","First ____. Then ____.","It made me feel ____."]};function sentHtml(st){const wk=st&&st.parts&&st.parts[0]&&st.parts[0].wk||"facts";return`<ul class="starters">${(STARTERS[wk]||STARTERS.facts).map(x=>`<li>${x}</li>`).join("")}</ul>`}function tpsCmpHtml(){const bar=(y,w,fill,lab2)=>`<rect x="46" y="${y}" width="${w}" height="26" rx="7" fill="${fill}" stroke="var(--fig-ink)" stroke-width="2.5"/><text x="${54+w}" y="${y+14}" font-size="17" dominant-baseline="central" fill="var(--ink)">${lab2}</text>`;const svg=`<svg viewBox="0 0 370 128" width="350" style="max-width:100%" role="img" aria-label="Two bars that both start at the same line. The top bar is longer and the bottom bar is shorter."><line x1="46" y1="14" x2="46" y2="110" stroke="var(--fig-ink)" stroke-width="3" stroke-dasharray="6 5"/>${bar(28,196,"var(--gold)","longer")}${bar(74,112,"var(--gold)","shorter")}<text x="46" y="124" font-size="14" text-anchor="middle" fill="var(--muted)">start</text></svg>`;return`<div class="figure">${svg}</div>`+F.table(["Word","What it means"],[["longer","it goes past the other one"],["shorter","it stops before the other one"],["taller","it goes higher than the other one"],["the same","they both end in the same place"]])+`<p class="small">Line both things up at the same start line. Then look at the other end to see which one goes further.</p>`}const tpsIco=(n,px)=>(F.icon||F.pic2)(n,px)||"";const TPS_ABC=[["a","apple","apple"],["b","bear","bear"],["c","cat","cat"],["d","dog","dog"],["e","egg","egg"],["f","fish","fish"],["g","goat","goat"],["h","hen","hen"],["i","island","island"],["j","jam",""],["k","key","key"],["l","leaf","leaf"],["m","moon","moon"],["n","nose","nose"],["o","octopus","octopus"],["p","pig","pig"],["q","queen",""],["r","rabbit","rabbit"],["s","sun","sun"],["t","tent","tent"],["u","umbrella","umbrella"],["v","van",""],["w","wave","wave"],["x","box, x at the end","box"],["y","yarn",""],["z","zip",""]];function tpsLetterHtml(){const cell=c=>`<div style="display:flex;flex-direction:column;align-items:center;gap:2px;min-width:70px;padding:6px 4px;border:2px solid var(--line);border-radius:10px"><b style="font-size:1.45rem;line-height:1">${c[0]} ${c[0].toUpperCase()}</b>${c[2]?tpsIco(c[2],30):""}<span style="font-size:.9rem;text-align:center">${c[1]}</span></div>`;return`<div class="tool-scroll"><div style="display:flex;flex-wrap:wrap;gap:6px;justify-content:center">${TPS_ABC.map(cell).join("")}</div></div><ul class="frames"><li>Point to a letter and ask for its sound, not its name.</li><li>Rhyme: two words that end with the same sounds, like cat and hat.</li><li>Word parts: clap once for each part you hear. Cam-per is two claps.</li><li>First sound: say only the sound at the start of the word.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who was there and where it was","First, ____."],["2. Next","what happened","Then, ____."],["3. Last","how it ended","Last, ____."]])+`<p class="small">Tell the three parts in that order. The card gives the order words, so the student supplies what happened.</p>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={np:{name:"Number line 0 to 20",std:["1.NBT.A.1","1.NBT.B.2","1.OA.A.1","K.CC.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:()=>window.TPNL20(),bind:(b,r)=>window.TPNL20Bind(b,r)},tf:{name:"Ten frames",std:["1.MD.C.4","1.NBT.B.2","1.OA.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},sent:{name:"Sentence starters",std:["W.K.1","W.K.2","W.K.3","W.K.8"],html:sentHtml},cmp:{name:"Longer and shorter card",std:["K.MD.A.2"],html:tpsCmpHtml},letters:{name:"Letter and sound card",std:["RF.K.1","RF.K.2","RF.K.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["SL.K.4","W.K.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.K.1","RI.K.1","RL.K.1","SL.K.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.K.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"np",std:["K.CC.A.1"],msg:"The number line shows the counting order, so counting done with it is supported, not independent."},{t:"np",std:["K.CC.B.4"],msg:"If the student read the answer off the number line instead of counting the pictures, note it. The point of this stop is that the last number said is the answer."},{t:"np",std:["K.OA.A.2"],msg:"If the student counted up or back along the number line, note that the answer came from a visual, not from knowing the combination."},{t:"tf",std:["K.NBT.A.1"],msg:"The ten frame does the ten-and-some-more split for the student. Note whether the student could still say the number as a ten and some ones without it."},{t:"sent",msg:"Sentence starters give the student the opening words, so count those checks as supported, not independent."},{t:"passage",std:["RF.K.4","RF.K.3"],msg:"If the lines on the screen were read to the student, this part shows listening, not reading. Rate it only if the student read the lines."},{t:"scribe",std:["W.K.1","W.K.2"],msg:"Telling an adult what to write is allowed at this grade. Note it, and do not rate the printing from this stop."},{t:"np",std:["K.CC.C.6"],msg:"The number line shows which number comes later, so the student can compare without counting the pictures. Note that the comparing was supported."},{t:"np",std:["K.OA.A.3"],msg:"If the student hopped along the number line to find the second part, note that the pair came from a visual rather than from knowing the combination."},{t:"np",std:["K.MD.B.3"],msg:"If the number line was used to put the three counts in order, note that the ordering was supported."},{t:"tf",std:["K.CC.C.6"],msg:"Matching the two groups on the ten frames is exactly the matching strategy this standard allows, so it still counts. Note that the model was used."},{t:"tf",std:["K.OA.A.3"],msg:"The ten frames let the student move counters into two groups. That is the drawing-or-objects route the standard allows, so it counts. Note it."},{t:"scribe",std:["W.K.3"],msg:"Dictating the story to an adult is allowed at this grade. Note it, and do not rate the printing from this stop."},{t:"cmp",std:["K.MD.A.2"],msg:"The card supplies the words longer, shorter and taller, so rate on whether the student picks the right one, not on producing the word."},{t:"letters",std:["RF.K.1","RF.K.3"],msg:"The letter and sound card shows a keyword and a picture for each letter, so a sound read off the card is supported, not known by heart."},{t:"letters",std:["RF.K.2"],msg:"RF.K.2 is listening only. If the card was open, note that the student had the rhyme and the clapping rule in front of them."},{t:"retell",std:["SL.K.4","W.K.3"],msg:"The card gives the order words first, then and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.K.1","RI.K.1","L.K.1","SL.K.2","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.K.4"],msg:"A read with the reading window open is not a clean fluency check. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:["RF.K.4"]}}});
